import mathimport randomimport pygamefrom scripts.particles import Particlefrom scripts.sparks import Spark#DIRPATH = os.path.dirname(os.path.dirname(os.path.realpath(__file__)))class PhysicsEntity():    def __init__(self, game, player_type, pos, size):        super().__init__()        self.game = game        self.type = player_type        self.pos = list(pos)        self.size = size        self.velocity = [0, 0]        self.movement_speed = 3        self.collisions = {'up': False, 'down': False, 'left': False, 'right': False}                self.action = ''        self.anim_offset = (-3, -3) # allow for rendered animation to exceed hitbox        self.flip = False        self.set_action('idle')                self.last_movement = [0, 0]            def rect(self):        return pygame.Rect(self.pos[0], self.pos[1], self.size[0], self.size[1])        def set_action(self, action):        if action != self.action:            self.action = action            self.animation = self.game.assets[self.type + '/' + self.action].copy()    def update(self, tilemap, movement=(0, 0)):        self.collisions = {'up': False, 'down': False, 'left': False, 'right': False}                frame_movement = (movement[0] * self.movement_speed + self.velocity[0],                           movement[1] * self.movement_speed + self.velocity[1])        # frame_movement = (movement[0] + self.velocity[0],         #                   movement[1] + self.velocity[1])                     self.pos[0] += frame_movement[0] # x position        entity_rect = self.rect()        for rect in tilemap.physics_rects_around(self.pos):            if entity_rect.colliderect(rect): # player collision with tile                if frame_movement[0] > 0: # collision while player is moving right                    entity_rect.right = rect.left                    self.collisions['right'] = True                if frame_movement[0] < 0: # collision while player is moving left                    entity_rect.left = rect.right                        self.collisions['left'] = True                self.pos[0] = entity_rect.x # update player x position based on rect                        self.pos[1] += frame_movement[1] # y position        entity_rect = self.rect()        for rect in tilemap.physics_rects_around(self.pos):            if entity_rect.colliderect(rect): # player collision with tile                if frame_movement[1] > 0: # collision while player is moving down                    entity_rect.bottom = rect.top                    self.collisions['down'] = True                if frame_movement[1] < 0: # collision while player is moving up                    entity_rect.top = rect.bottom                       self.collisions['up'] = True                self.pos[1] = entity_rect.y # update player y position based on rect                        # flip player direction based of movement        if movement[0] > 0:            self.flip = False        if movement[0] < 0:            self.flip = True                    # store last movement        self.last_movement = movement                        # gravity: maximum velocity downwards (terminal velocity)        self.velocity[1] = min(5, self.velocity[1] + 0.1)                if self.collisions['down'] or self.collisions['up']:            self.velocity[1] = 0 # reset vertical velocity when player collides                    self.animation.update()                def render(self, surf, offset=(0, 0)):        surf.blit(pygame.transform.flip(self.animation.img(), self.flip, False),                  (self.pos[0] - offset[0] + self.anim_offset[0],                   self.pos[1] - offset[1] + self.anim_offset[1]))        class Enemy(PhysicsEntity):    def __init__(self, game, pos, size):        super().__init__(game, 'enemy', pos, size)                self.walking = 0            def update(self, tilemap, movement=(0, 0)):        if self.walking:            # check if enemy is walking off edge or hitting wall, and turn enemy around if it is            if tilemap.solid_check((self.rect().centerx + (-self.rect().width // 2 if self.flip else self.rect().width // 2),                                    self.pos[1] + self.rect().height)):                if (self.collisions['right'] or self.collisions['left']):                    self.flip = not self.flip                else:                    movement = (movement[0] - 0.5 if self.flip else 0.5, movement[1])            else:                self.flip = not self.flip                            self.walking = max(0, self.walking - 1) # reduce walking time counter                        # enemy shoots as soon as it stops walking (shoot when walking timer runs out)            if not self.walking:                # calculate distance between enemy and player                dis = (self.game.player.pos[0] - self.pos[0],                       self.game.player.pos[1] - self.pos[1])                if (abs(dis[1]) < 34):                    if (self.flip and dis[0] < 0): # if player is to the left and looking left                        # spawn projectile: [[x, y], direction, timer]                        self.game.projectiles.append(                            [[self.rect().left + self.rect().width // 4,                               self.rect().centery + self.rect().height // 8], -3, 0])                        for i in range(4):                            self.game.sparks.append(Spark(self.game.projectiles[-1][0], # last projectile position                                                          random.random() - 0.5 + math.pi, # random angle to the left                                                          2 + random.random())) # random speed                    if (not self.flip and dis[0] > 0): # if player is to the right and looking right                        self.game.projectiles.append(                            [[self.rect().right - self.rect().width // 4,                               self.rect().centery + self.rect().height // 8], 3, 0])                        for i in range(4):                            self.game.sparks.append(Spark(self.game.projectiles[-1][0], # last projectile position                                                          random.random() - 0.5, # random angle to the right                                                          2 + random.random())) # random speed                # if enemy is not walking, 1/100 frame chance of enemy starting to walk        elif random.random() < 0.01:            # enemy will walk for anywhere between 0.5 to 2 seconds (at 60 fps)            self.walking = random.randint(30, 120)                    super().update(tilemap, movement=movement)                if movement[0] != 0:            self.set_action('walk')        else:            self.set_action('idle')                def render(self, surf, offset=(0, 0)):        super().render(surf, offset=offset)                if self.flip:            surf.blit(pygame.transform.flip(self.game.assets['gun'], True, False),                      (self.rect().left + self.rect().width // 4 - self.game.assets['gun'].get_width() - offset[0], # offset gun by 4 pixels                       self.rect().centery - offset[1]))        else:            surf.blit(self.game.assets['gun'],                      (self.rect().right - self.rect().width // 4 - offset[0], # offset gun by 4 pixels                       self.rect().centery - offset[1]))            class Player(PhysicsEntity):    def __init__(self, game, pos, size):        super().__init__(game, 'player', pos, size)        self.air_time = 0        self.jumps = 3 # n jumps        self.wall_slide = False        self.dashing = 0            def update(self, tilemap, movement=(0, 0)):        super().update(tilemap, movement=movement)                self.air_time += 1        if self.collisions['down']:            self.air_time = 0            self.jumps = 3 # n jumps                    self.wall_slide = False # single frame event trigger as inside update        if (self.collisions['right'] or self.collisions['left']) and self.air_time > 4:            self.wall_slide = True            # slow down descent when sliding down wall            self.velocity[1] = min(self.velocity[1], 0.5)             # set player direction when on wall            if self.collisions['right']:                self.flip = False            else:                self.flip = True            self.set_action('wall_slide')                    if not self.wall_slide:            if self.air_time > 4:                self.set_action('jump')            elif movement[0] != 0:                self.set_action('walk')            else:                self.set_action('idle')                           # burst of particles for dash                        if abs(self.dashing) in {60, 50}:            # create 20 particles at start and end of dash            for i in range(20):                # random angle in full circle of angles in radians                # convert polar coords into cartesian vector of velocity                angle = random.random() * math.pi * 2                # random speed between 0.5 and 1                speed = random.random() * 0.5 + 0.5                pvelocity = [math.cos(angle) * speed, # x-axis velocity based on angle                             math.sin(angle) * speed] # y-axis velocity based on angle                # TODO: look into using arctan to turn an x,y coord into an angle                self.game.particles.append(Particle(self.game,                                                     'woosh',                                                     self.rect().center,                                                     velocity=pvelocity,                                                    frame=random.randint(0, 7)))                    # drag to slow horizontal velocity after jumping off wall        if self.velocity[0] > 0:            self.velocity[0] = max(self.velocity[0] - 0.1, 0)        else:            self.velocity[0] = min(self.velocity[0] + 0.1, 0)        # drag to slow horizontal velocity after dashing        if self.dashing > 0:            self.dashing = max(0, self.dashing - 1)        if self.dashing < 0:            self.dashing = min(0, self.dashing + 1)                # reduce velocity throughout the dash (after 10 frames, as 60-50=10)        # last 50 frames are for cooldown time after the dash        if abs(self.dashing) > 50:            self.velocity[0] = abs(self.dashing) / self.dashing * 8            # dividing abs(x)/x gives the direction of the scalar (either 1 or -1)            if abs(self.dashing) == 51:                self.velocity[0] *= 0.1                    # stream of particles for dash            # random number from 0 to 3 in the direction player is dashing            pvelocity = [abs(self.dashing) / self.dashing * random.random() * 3, 0]            self.game.particles.append(Particle(self.game,                                                 'woosh',                                                 self.rect().center,                                                 velocity=pvelocity,                                                frame=random.randint(0, 7)))    def render(self, surf, offset=(0, 0)):        # if not in first 10 frames of dash        if abs(self.dashing) <= 50:            # inherit render function of PhysicsEntity as normal            super().render(surf, offset=offset)        else:            pass                            def jump(self):        if self.wall_slide:            if self.flip and self.last_movement[0] < 0:                self.velocity[0] = 3.5 # jump right off wall                self.velocity[1] = -2.5 # also jump up off wall                self.air_time = 5                self.jumps = max(0, self.jumps - 1)                return True            elif not self.flip and self.last_movement[0] > 0:                self.velocity[0] = -3.5 # jump left off wall                self.velocity[1] = -2.5 # also jump up off wall                self.air_time = 5                self.jumps = max(0, self.jumps - 1)                return True                        elif self.jumps:            self.velocity[1] = -3            self.jumps -= 1 # reduce jump count            self.air_time = 5            return True                def dash(self):        if not self.dashing:            if self.flip: # if facing left, dash left                self.dashing = -60            else:                self.dashing = 60            def dig(self):        pass     # TODO: Add dig animation to player besed on whether dig key pressed    # TODO: update tilemap to remove tile that was dug by player    # class Player(pygame.sprite.Sprite):#     def __init__(self, game, player_type, pos, size):#         super().__init__()#         self.game = game#         self.type = player_type#         self.pos = list(pos)#         self.size = size#         self.velocity = [0, 0]        #         self.scale_img_by = 0.05#         self.player_walk_frames = load_frames(DIRPATH + '/graphics/' + #                                               self.type + '/walk/', #                                               scale_by=self.scale_img_by)#         self.animation_index = 0 # default: first frame#         self.direction = 1 # default: right#         self.player_jump = load_frames(DIRPATH + '/graphics/' + #                                        self.type + '/jump/',#                                        rotation=30, scale_by=self.scale_img_by)[0] # TODO: update to animation?#         self.player_dig = load_frames(DIRPATH + '/graphics/' + #                                       self.type + '/dig/',#                                       rotation=-5, scale_by=self.scale_img_by)[0] # TODO: update to 